-- Biochemistry Ch2: Enzymes — BATCH 1 (Catalysts, EC Classification, Active Site / Lock-and-Key & Induced Fit)
-- discipline=biochemistry, foundation=1A. Safe to re-run: deletes only this batch's subtopics, then re-inserts.

DELETE FROM questions WHERE topic = 'Enzymes' AND subtopic IN ('Enzymes as Catalysts', 'Enzyme Classification (EC Classes)', 'Active Site, Lock-and-Key & Induced Fit');

-- Q1 [Enzymes as Catalysts] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Enzymes as Catalysts', 'A cell expresses an enzyme that accelerates the conversion of a substrate to product in a reversible reaction. By acting as a biological catalyst, the enzyme speeds the reaction by changing which quantity?', '[{"label": "A", "text": "It lowers the activation energy"}, {"label": "B", "text": "It raises the activation energy"}, {"label": "C", "text": "It makes \\(\\Delta G\\) more negative"}, {"label": "D", "text": "It increases the equilibrium constant \\(K_\\text{eq}\\)"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because an enzyme is a biological catalyst that speeds a reaction by lowering the activation energy (\(E_a\)) required to reach the transition state, without altering the reaction''s thermodynamics. LibreTexts states that "enzymes dramatically increase the rate at which equilibrium is reached by lowering the activation energy" and that "Enzymes do not affect the thermodynamics of reactions... the equilibrium constant, Keq, is unchanged." OpenStax Biology echoes that enzymes "do not change the reaction''s ∆G... They only reduce the activation energy required to reach the transition state." Thus the enzyme changes how fast equilibrium is reached, not where the equilibrium lies. (Choice A) is correct: lowering \(E_a\) is precisely how a catalyst accelerates the reaction. (Choice B) is wrong because raising \(E_a\) would slow the reaction, the opposite of catalysis. (Choice C) is wrong because an enzyme does not change the free energy of reactants or products, so \(\Delta G\) is unchanged and the reaction remains exergonic or endergonic regardless of the enzyme. (Choice D) is wrong because the enzyme leaves \(K_\text{eq}\) and the equilibrium position unchanged; it only changes the rate at which that equilibrium is reached. This is a Knowledge of Scientific Concepts and Principles question because you must recall the core definition of an enzyme as a catalyst that lowers activation energy without altering reaction thermodynamics.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 70)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', NULL FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', NULL FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', NULL FROM q;

-- Q2 [Active Site, Lock-and-Key & Induced Fit] easy skill1 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Active Site, Lock-and-Key & Induced Fit', 'Trypsin and chymotrypsin are homologous pancreatic serine proteases, yet trypsin cleaves peptides only after basic residues such as lysine and arginine while chymotrypsin cleaves only after bulky aromatic residues such as phenylalanine. A student investigating why two such similar enzymes act on different substrates would most likely attribute the difference to which feature of each enzyme?', '[{"label": "A", "text": "The activation energy each enzyme lowers"}, {"label": "B", "text": "The free-energy change of each cleavage reaction"}, {"label": "C", "text": "The optimal temperature of each enzyme"}, {"label": "D", "text": "The residues lining its substrate-binding pocket"}]'::jsonb, 'D', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is D because an enzyme''s substrate specificity comes from the amino acid residues that line its substrate-binding pocket, whose size, shape, and charge determine which side chain can dock. LibreTexts states that for serine proteases the specificity is "determined by the size/shape/charge of the amino acid side chain that fits into the enzyme''s S1 binding pocket," and that "variations in the amino acid residues within the binding pocket of these proteases enable electrostatic interactions with the substrate and determine sequence specificity." Because trypsin''s S1 pocket contains an aspartate that attracts basic side chains while chymotrypsin''s pocket is large and hydrophobic and accommodates aromatic side chains, the two homologous enzymes recognize different substrates. (Choice A) is incorrect: lowering the activation energy is a property shared by all enzymes (''Enzymes lower the activation energy for bound transition states''), so it cannot explain why these two enzymes select different substrates. (Choice B) is incorrect: both enzymes catalyze the same chemistry, peptide-bond hydrolysis, and an enzyme ''do[es] not affect the thermodynamics of reactions,'' so the reaction''s free-energy change is neither set by the enzyme nor the source of its specificity. (Choice C) is incorrect: temperature changes globally affect reaction rate and denaturation (''Moderate increases in temperature typically enhance reaction rates, whereas excessive heat leads to irreversible denaturation''), but they do not dictate which side chain a protease recognizes. (Choice D) is correct: the identity of the residues forming the binding pocket sets the size/shape/charge complementarity that determines substrate specificity. This is a Knowledge of Scientific Concepts and Principles question because you must recall that an enzyme''s substrate specificity is set by the residues lining its binding pocket.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 75)
  RETURNING id
)
