-- Q3 [Enzymes as Catalysts] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Enzymes as Catalysts', 'A researcher measures that an uncatalyzed metabolic reaction is endergonic (\(\Delta G>0\)) and proceeds far too slowly to support the cell. After adding the specific enzyme that catalyzes this reaction, the researcher observes a dramatic increase in reaction rate. With the enzyme present, which of the following is true of the reaction?', '[{"label": "A", "text": "Its \\(\\Delta G\\) is unchanged"}, {"label": "B", "text": "Its \\(\\Delta G\\) becomes negative"}, {"label": "C", "text": "Its equilibrium shifts toward products"}, {"label": "D", "text": "Its \\(K_\\text{eq}\\) increases"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because an enzyme is a biological catalyst that speeds a reaction only by lowering the activation energy (\(E_a\)) needed to reach the transition state; it does not alter the reactants'' or products'' free energy, so the reaction''s \(\Delta G\) is unchanged. OpenStax states it is "important to remember that enzymes do not change the reaction''s ∆G ... they do not change whether a reaction is exergonic (spontaneous) or endergonic" (lines 8456-8458), and LibreTexts confirms that "enzymes do not affect the thermodynamics of reactions ... the equilibrium constant, Keq, is unchanged. What is changed is the rate at which equilibrium is achieved" (lines 26826-26828). An endergonic reaction therefore remains endergonic with the enzyme present; the enzyme only makes it reach equilibrium faster. (Choice A) is correct: \(\Delta G\) depends solely on the free energy of reactants and products, which the enzyme does not touch. (Choice B) is wrong because the enzyme does not lower \(\Delta G\) or flip its sign; a positive \(\Delta G\) stays positive. (Choice C) is wrong because the enzyme increases only the rate at which equilibrium is reached, not the equilibrium position; the balance of reactants and products is unchanged. (Choice D) is wrong because \(K_\text{eq}\) reflects the equilibrium position, which the enzyme leaves unchanged—it only increases how fast equilibrium is reached, not where it lies. This is a Scientific Reasoning and Problem Solving question because you must apply the principle that catalysis affects kinetics but not thermodynamics to a specific endergonic reaction.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 105)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', NULL FROM q
  UNION ALL
  SELECT id, 'C', 'partial_truth', NULL FROM q
  UNION ALL
  SELECT id, 'D', 'adjacent_fact', NULL FROM q;

-- Q4 [Enzymes as Catalysts] medium skill1 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Enzymes as Catalysts', 'A researcher compares the same chemical reaction running with and without its enzyme and finds that the enzyme speeds the reaction without altering \(\Delta G\) or \(K_\text{eq}\). According to Pauling''s hypothesis, the enzyme achieves this acceleration primarily because it binds and', '[{"label": "A", "text": "stabilizes the free substrate"}, {"label": "B", "text": "stabilizes the product"}, {"label": "C", "text": "stabilizes the transition state"}, {"label": "D", "text": "raises the transition-state energy"}]'::jsonb, 'C', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because an enzyme accelerates a reaction by binding the transition state more tightly than the free substrate, which lowers the energy of the transition state and therefore lowers the activation energy \(E_a\). Pauling postulated that "the only thing that a catalyst must do is bind the transition state more tightly than the substrate," and stabilizing the transition state is what catalyzes the reaction. Because the enzyme only changes the rate at which equilibrium is reached, the thermodynamics — \(\Delta G\) and \(K_\text{eq}\) — are unchanged, exactly as observed. (Choice A) is incorrect: tightly binding the free substrate would deepen the starting energy well and effectively increase \(E_a\) rather than lower it; the enzyme must bind the transition state MORE tightly than the substrate, not the reverse. (Choice B) is incorrect: stabilizing the product lowers the product''s energy and would shift the equilibrium position, yet enzymes leave \(\Delta G\) and \(K_\text{eq}\) unchanged, so product stabilization is not the catalytic mechanism. (Choice C) is correct: binding the transition state more tightly than the substrate lowers its energy, reduces \(E_a\), and speeds the reaction without altering \(\Delta G\) or \(K_\text{eq}\). (Choice D) is incorrect: this reverses the mechanism — raising the transition-state energy would increase \(E_a\) and slow the reaction, whereas catalysts LOWER the energy of the transition state. This is a Knowledge of Scientific Concepts and Principles question because you must recall that enzymes lower activation energy by stabilizing the transition state while leaving reaction thermodynamics unchanged.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 100)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', NULL FROM q
  UNION ALL
  SELECT id, 'B', 'misconception', NULL FROM q
  UNION ALL
  SELECT id, 'D', 'reversed_relationship', NULL FROM q;

-- Q5 [Enzymes as Catalysts] medium skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Enzymes as Catalysts', 'An energy diagram for an uncatalyzed reaction shows the reactant free-energy level above the product free-energy level, with a single energy peak rising between them. An enzyme that catalyzes this reaction is then added. On the new diagram with the enzyme present, what feature differs from the original?', '[{"label": "A", "text": "The product level is lowered"}, {"label": "B", "text": "The reactant level is raised"}, {"label": "C", "text": "Both endpoint levels shift downward"}, {"label": "D", "text": "The peak is lower; endpoints unchanged"}]'::jsonb, 'D', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is D because an enzyme lowers only the activation energy (\(E_a\)) — the height of the peak between reactant and product — while leaving the reactant and product free-energy endpoints exactly where they were. OpenStax states that enzymes "do not change the reactants'' or products'' free energy. They only reduce the activation energy required to reach the transition state" (OpenStax Biology 2e, lines 8459-8461), and the Figure 6.15 caption confirms "Enzymes lower the reaction''s activation energy but do not change the reaction''s free energy" (line 8465). LibreTexts reinforces this with the diagram itself: because "the distance between the two horizontal blue lines is the same for the left-hand process (uncatalyzed) and the right-hand one (catalyzed)," the endpoints and therefore \(\Delta G\) are identical, and only the activation-energy barrier shrinks (LibreTexts Biochemistry, line 25592). Since \(\Delta G\) is fixed by the unchanged endpoints, the enzyme changes only how FAST the reaction proceeds, not its thermodynamics. (Choice A) is incorrect: lowering the product level would change the reactant-to-product gap and therefore \(\Delta G\), but the text states the products'' free energy is not changed (OpenStax lines 8459-8461). (Choice B) is incorrect: raising the reactant level would likewise alter \(\Delta G\); the enzyme does not change the reactants'' free energy (OpenStax lines 8459-8461). (Choice C) is incorrect: shifting both endpoints down treats the whole curve as sliding, but the diagram shows the endpoint-to-endpoint distance is identical in catalyzed and uncatalyzed cases — only the peak between them is lowered (LibreTexts line 25592). (Choice D) is correct: only the peak (\(E_a\)) is lowered while both endpoints, and thus \(\Delta G\), stay the same (OpenStax lines 8459-8461, 8465; LibreTexts line 25592). This is a Scientific Reasoning and Problem Solving question because you must apply the principle that enzymes lower activation energy without altering reaction thermodynamics to predict how a described energy diagram changes.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 105)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', NULL FROM q
  UNION ALL
  SELECT id, 'B', 'misconception', NULL FROM q
