-- Q8 [Enzymes as Catalysts] medium skill1 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Enzymes as Catalysts', 'A researcher characterizes a newly isolated enzyme and finds that its active site is lined with a particular arrangement of amino acid residues that forms a distinctive local chemical environment. This feature most directly accounts for the enzyme''s:', '[{"label": "A", "text": "ability to catalyze any reaction"}, {"label": "B", "text": "capacity to make the reaction''s \\(\\Delta G\\) more negative"}, {"label": "C", "text": "high specificity for its substrate"}, {"label": "D", "text": "requirement for an elevated reaction temperature"}]'::jsonb, 'C', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because the unique combination of amino acid residues within the active site creates a very specific chemical environment that is suited to bind a particular substrate. As OpenStax states, the active site''s distinctive arrangement of residues means that ''enzymes are known for their specificity,'' and ''there is a specifically matched enzyme for each substrate and, thus, for each chemical reaction.'' Thus, the described residue arrangement is what makes the enzyme selective for its substrate. (Choice A) is incorrect: an enzyme does not catalyze any reaction; because of this complementary active-site environment, it is matched to a specific substrate and reaction, not to reactions in general. (Choice B) is incorrect: enzymes ''lower the reaction''s activation energy but do not change the reaction''s free energy,'' so the active-site environment determines substrate specificity, not the magnitude or sign of \(\Delta G\). (Choice C) is correct: the unique active-site residues form a specific environment ''suited to bind, albeit briefly, to a specific chemical substrate,'' which is the structural basis of substrate specificity. (Choice D) is incorrect: increasing temperature raises reaction rates generally and, outside the optimal range, distorts active-site bonds and eventually denatures the enzyme; elevated temperature is not the source of substrate specificity. This is a Knowledge of Scientific Concepts and Principles question because you must recall that the unique active-site environment is the basis of an enzyme''s substrate specificity.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 100)
  RETURNING id
)
