-- Q9 [Enzyme Classification (EC Classes)] easy skill1 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Enzyme Classification (EC Classes)', 'An enzyme catalyzes a reaction in which a reducing agent donates electrons to an oxidizing agent, transferring electrons from the donor to the acceptor. Into which Enzyme Commission class does this enzyme fall?', '[{"label": "A", "text": "Transferase"}, {"label": "B", "text": "Oxidoreductase"}, {"label": "C", "text": "Ligase"}, {"label": "D", "text": "Lyase"}]'::jsonb, 'B', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is B because an enzyme that catalyzes a redox reaction — the transfer of electrons from a donor to an acceptor — is an oxidoreductase, the first of the six EC classes. OpenStax states that "a compound that reduces another is called a reducing agent" and "a compound that oxidizes another is called an oxidizing agent," so the reducing agent is the electron donor and the oxidizing agent is the electron acceptor; an enzyme catalyzing this electron transfer is by definition an oxidoreductase. LibreTexts confirms that in the EC numbering system the "1st digit: Represents one of the six primary classes of enzymes, e.g., ''1'' stands for oxidoreductases." (Choice A) Transferases (EC2) move a functional group between molecules — for example a protein kinase that "covalently transfers a terminal phosphate (P) from ATP to a protein" — not electrons in a redox reaction. (Choice B) is correct: oxidoreductases catalyze electron transfer between an electron donor (reducing agent) and an electron acceptor (oxidizing agent). (Choice C) Ligases join two molecules into a larger one, as DNA ligase does when it seals fragments and "creates a phosphodiester bond," which is a bond-forming joining reaction, not electron transfer. (Choice D) Lyases, such as hydroxynitrile lyase, cleave a molecule into two pieces (or the reverse) without using water and without a redox change, so an electron-transfer reaction does not fit this class. This is a Knowledge of Scientific Concepts and Principles question because you must recall that an enzyme catalyzing electron transfer between a donor and acceptor is an oxidoreductase.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 75)
  RETURNING id
)
