-- Q12 [Enzyme Classification (EC Classes)] medium skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Enzyme Classification (EC Classes)', 'An enzyme catalyzes the conversion of glucose-6-phosphate to fructose-6-phosphate. Tracking every atom shows that the product has the same molecular formula as the substrate, with no atoms added or removed and no second molecule involved. Based on this reaction, the enzyme is best classified as which of the following?', '[{"label": "A", "text": "Isomerase"}, {"label": "B", "text": "Transferase"}, {"label": "C", "text": "Lyase"}, {"label": "D", "text": "Ligase"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because the reaction rearranges the bonds within a single molecule to interconvert two isomers without gaining or losing any atoms, which is the defining feature of an isomerase. LibreTexts classifies isomerases (EC5) as catalyzing "conversions of geometric, stereo- or constitutive isomers," and lists phosphoglucose isomerase as the enzyme that converts glucose-6-phosphate to fructose-6-phosphate. Because glucose-6-phosphate and fructose-6-phosphate share an identical molecular formula and only the arrangement of atoms changes (an aldose-to-ketose interconversion), no group is transferred, no bond is cleaved, and no second molecule is joined. (Choice A) is correct: a single molecule is rearranged into its isomer with no net change in atoms, which is exactly an isomerase-catalyzed reaction. (Choice B) is wrong because a transferase catalyzes "transfer/exchange of group from one molecule to another" (e.g., a kinase moving a phosphate from \(\text{ATP}\)); here only one molecule participates and no group is handed off. (Choice C) is wrong because a lyase performs an "elimination forming a double bond," cleaving a substrate into two products without water; this reaction produces only one product and breaks the molecule into no separate pieces. (Choice D) is wrong because a ligase catalyzes "condensation of two molecules into one," typically requiring \(\text{ATP}\); no two molecules are joined in this single-substrate interconversion. This is a Scientific Reasoning and Problem Solving question because you must apply the EC classification scheme to a described reaction and reason from the conserved atom count to assign the correct enzyme class.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 105)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'adjacent_fact', NULL FROM q
