-- Q16 [Enzyme Classification (EC Classes)] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Enzyme Classification (EC Classes)', 'A protein tyrosine phosphatase removes a phosphate group from a phosphorylated tyrosine residue, regenerating the free hydroxyl side chain. The enzyme accomplishes this by adding a molecule of water across the phosphoester bond rather than passing the phosphate to another acceptor molecule. To which EC class does this enzyme belong?', '[{"label": "A", "text": "Lyase"}, {"label": "B", "text": "Isomerase"}, {"label": "C", "text": "Hydrolase"}, {"label": "D", "text": "Transferase"}]'::jsonb, 'C', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because the defining feature of the reaction is that water is the second substrate: the enzyme cleaves the phosphoester bond by adding H2O, which is the hallmark of a hydrolase. LibreTexts shows that dephosphorylation by phosphatases consumes H2O (line 6250: "phosphatases ... H2O"), and describes a protein tyrosine phosphatase as "an enzyme that, in its active form, hydrolyzes p-Tyr on specific phosphorylated target proteins" (lines 7945-7946); the text explicitly groups such phosphatases with the hydrolases (line 28773: "hydrolases (EC3)"). Because the phosphate is released by hydrolysis rather than handed off to an acceptor, the enzyme is a hydrolase, not a transferase. (Choice A) Lyase is wrong because lyases cleave a substrate into two pieces (or run the reverse synthesis) WITHOUT using water and without redox; here water is explicitly added, so the reaction is a hydrolysis, not a lyase-type elimination. (Choice B) Isomerase is wrong because isomerases rearrange bonds within a single molecule to interconvert isomers, such as the formation of a single stereoisomer by triose phosphate isomerase (line 25130); no phosphate is removed and no water is added. (Choice C) is correct: the enzyme breaks the phosphoester bond by adding water, the defining reaction of a hydrolase, consistent with a phosphatase that hydrolyzes p-Tyr (lines 6250, 7945-7946, 28773). (Choice D) is the tempting trap because the enzyme does act on a phosphate group, which makes "transferase" feel right; however, a transferase MOVES a functional group from a donor to an acceptor, as a kinase transfers a phosphate, whereas a phosphatase HYDROLYZES the phosphate off using water (line 30843: kinases and phosphatases "phosphorylate and dephosphorylate substrates, respectively"). Transfer versus hydrolysis is the single distinction, and the stem specifies water is added rather than the phosphate being passed to an acceptor. This is a Scientific Reasoning and Problem Solving question because you must apply the EC classification criteria to a described reaction and recognize that the use of water as the second substrate assigns the enzyme to the hydrolase class rather than the transferase class.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 150)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'adjacent_fact', NULL FROM q
