-- Q18 [Active Site, Lock-and-Key & Induced Fit] easy skill1 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Active Site, Lock-and-Key & Induced Fit', 'A researcher studying a newly isolated hydrolase wants to identify the specific region of the enzyme where the substrate binds and the catalytic chemistry takes place. Which region of the enzyme should the researcher target?', '[{"label": "A", "text": "The allosteric site"}, {"label": "B", "text": "The active site"}, {"label": "C", "text": "The substrate itself"}, {"label": "D", "text": "The cofactor"}]'::jsonb, 'B', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is B because the active site is the part of an enzyme that directly binds the substrate and carries out the catalytic reaction. LibreTexts states, "An active site is the part of an enzyme that directly binds to a substrate and carries out a reaction" (lines 5268-5269), and OpenStax notes, "The location within the enzyme where the substrate binds is the enzyme''s active site. This is where the ''action'' happens" (lines 8471-8472). The active site is formed by a unique combination of amino acid R-groups that create a specific chemical environment suited to bind the substrate, so it is the correct region to target. (Choice A) The allosteric site is "a location other than the active site," where a regulator binds away from where the substrate binds (OpenStax 8568-8569); it is a regulatory site, not the catalytic binding region. (Choice B) is correct: the active site directly binds the substrate and carries out the reaction. (Choice C) The substrate is the molecule that binds to the enzyme, not a region of the enzyme; "the substrate binds" to the active site (OpenStax 8472), so the substrate cannot be the binding site. (Choice D) A cofactor is a non-protein helper molecule, an "inorganic ion such as iron and magnesium" (OpenStax 8638), that assists catalysis but is not the region of the enzyme where the substrate binds. This is a Knowledge of Scientific Concepts and Principles question because you must recall the definition and function of the enzyme active site.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 75)
  RETURNING id
)
